export declare function CashFlowStructInvestingActivitiesFromJSONTyped(json: any, ignoreDiscriminator: boolean): CashFlowStructInvestingActivities;
export declare function CashFlowStructInvestingActivitiesToJSON(json: any): CashFlowStructInvestingActivities;
